@@ -7,5 +7,37 @@

 /** Split a template into text and tag tokens. See README.md. */
 export function tokenize(template: string): Token[] {
-  throw new Error("not implemented");
+  const tokens: Token[] = [];
+  let text = "";
+  let i = 0;
+  while (i < template.length) {
+    if (template[i] === "{" && template[i + 1] === "{") {
+      const raw = template[i + 2] === "{";
+      const close = raw ? "}}}" : "}}";
+      const closeStart = template.indexOf(close, i + (raw ? 3 : 2));
+      if (closeStart === -1) throw new Error("unterminated tag");
+      const inner = template.slice(i + (raw ? 3 : 2), closeStart).trim();
+      if (text !== "") {
+        tokens.push({ kind: "text", text });
+        text = "";
+      }
+      if (raw) {
+        tokens.push({ kind: "value", expr: inner, raw: true });
+      } else if (inner.startsWith("#if")) {
+        tokens.push({ kind: "if", path: inner.slice(3).trim() });
+      } else if (inner === "else") {
+        tokens.push({ kind: "else" });
+      } else if (inner === "/if") {
+        tokens.push({ kind: "end" });
+      } else {
+        tokens.push({ kind: "value", expr: inner, raw: false });
+      }
+      i = closeStart + close.length;
+    } else {
+      text += template[i];
+      i += 1;
+    }
+  }
+  if (text !== "") tokens.push({ kind: "text", text });
+  return tokens;
 }
